#include "Jinja2Tools/Protocol.h"
#include <rpc.h>
#pragma comment(lib,"Rpcrt4.lib")
namespace jinja2tools {std::string operationToString(Operation o){switch(o){case Operation::Ping:return"ping";case Operation::Validate:return"validate";case Operation::Format:return"format";case Operation::Analyze:return"analyze";case Operation::Shutdown:return"shutdown";}throw std::invalid_argument("Unknown operation");}void to_json(nlohmann::json&j,const DocumentPayload&v){j={{"name",v.name},{"text",v.text}};}void to_json(nlohmann::json&j,const HelperRequest&v){j={{"protocolVersion",v.protocolVersion},{"requestId",v.requestId},{"operation",operationToString(v.operation)},{"document",v.document}};}void from_json(const nlohmann::json&j,Diagnostic&v){j.at("severity").get_to(v.severity);j.at("code").get_to(v.code);j.at("message").get_to(v.message);v.source=j.value("source","");if(j.contains("line")&&!j["line"].is_null())v.line=j["line"].get<int>();if(j.contains("column")&&!j["column"].is_null())v.column=j["column"].get<int>();v.positionAccuracy=j.value("positionAccuracy",std::string{});v.exceptionType=j.value("exceptionType",std::string{});}void from_json(const nlohmann::json&j,HelperResponse&v){j.at("protocolVersion").get_to(v.protocolVersion);j.at("requestId").get_to(v.requestId);j.at("success").get_to(v.success);v.diagnostics=j.value("diagnostics",std::vector<Diagnostic>{});v.result=j.value("result",nlohmann::json(nullptr));}std::string createRequestId(){UUID u{};UuidCreate(&u);RPC_CSTR s{};UuidToStringA(&u,&s);std::string out((char*)s);RpcStringFreeA(&s);return out;} }
